import json
from itertools import permutations

def solve():
    houses = [1, 2, 3, 4]

    Names = ["Peter", "Arnold", "Eric", "Alice"]
    Flowers = ["daffodils", "carnations", "roses", "lilies"]
    Heights = ["very short", "short", "tall", "average"]
    Mothers = ["Janelle", "Kailyn", "Holly", "Aniya"]
    Occupations = ["engineer", "doctor", "teacher", "artist"]
    Sports = ["swimming", "basketball", "tennis", "soccer"]

    # State for backtracking
    solution = [None] * 4  # list of dicts for each house

    remaining = {
        "Name": set(Names),
        "Flower": set(Flowers),
        "Height": set(Heights),
        "Mother": set(Mothers),
        "Occupation": set(Occupations),
        "FavoriteSport": set(Sports),
    }

    # Position maps (value -> house index)
    pos_name = {}
    pos_flower = {}
    pos_height = {}
    pos_mother = {}
    pos_occupation = {}
    pos_sport = {}

    def check_partial_constraints():
        # Clue 4: daffodils to the right of engineer
        if "daffodils" in pos_flower:
            if "engineer" not in pos_occupation:
                return False
            if not (pos_occupation["engineer"] < pos_flower["daffodils"]):
                return False
        # If engineer is placed, ensure not in house 4 (needs someone to the right for daffodils)
        if "engineer" in pos_occupation:
            if pos_occupation["engineer"] == 4:
                return False

        # Clue 10: Holly to the right of average
        if "Holly" in pos_mother:
            if "average" not in pos_height:
                return False
            if not (pos_height["average"] < pos_mother["Holly"]):
                return False
        if "average" in pos_height:
            if pos_height["average"] == 4:
                return False
            if "Holly" in pos_mother:
                if not (pos_height["average"] < pos_mother["Holly"]):
                    return False

        # Equality constraints are enforced at candidate generation, so no need to re-check here.
        return True

    def add_assignment(i, cand):
        name, flower, height, mother, occupation, sport = cand
        solution[i-1] = {
            "House": str(i),
            "Name": name,
            "Flower": flower,
            "Height": height,
            "Mother": mother,
            "Occupation": occupation,
            "FavoriteSport": sport,
        }
        remaining["Name"].remove(name)
        remaining["Flower"].remove(flower)
        remaining["Height"].remove(height)
        remaining["Mother"].remove(mother)
        remaining["Occupation"].remove(occupation)
        remaining["FavoriteSport"].remove(sport)

        pos_name[name] = i
        pos_flower[flower] = i
        pos_height[height] = i
        pos_mother[mother] = i
        pos_occupation[occupation] = i
        pos_sport[sport] = i

    def remove_assignment(i, cand):
        name, flower, height, mother, occupation, sport = cand
        solution[i-1] = None
        remaining["Name"].add(name)
        remaining["Flower"].add(flower)
        remaining["Height"].add(height)
        remaining["Mother"].add(mother)
        remaining["Occupation"].add(occupation)
        remaining["FavoriteSport"].add(sport)

        del pos_name[name]
        del pos_flower[flower]
        del pos_height[height]
        del pos_mother[mother]
        del pos_occupation[occupation]
        del pos_sport[sport]

    def generate_candidates(i):
        cands = []
        for name in list(remaining["Name"]):
            # Clue 9: Arnold is not in the third house.
            if i == 3 and name == "Arnold":
                continue
            # Clue 6 and 11: Teacher in house1; Peter is doctor (so Peter cannot be in house 1)
            if i == 1 and name == "Peter":
                continue

            # Flower choices
            for flower in list(remaining["Flower"]):
                # Clue 2: The person who loves the rose bouquet is Eric.
                if (name == "Eric" and flower != "roses") or (name != "Eric" and flower == "roses"):
                    continue
                # Clue 13: Arnold loves lilies.
                if (name == "Arnold" and flower != "lilies") or (name != "Arnold" and flower == "lilies"):
                    continue

                # Height choices
                for height in list(remaining["Height"]):
                    # Clue 3: Arnold is tall.
                    if (name == "Arnold" and height != "tall") or (name != "Arnold" and height == "tall"):
                        continue

                    # Mother choices
                    for mother in list(remaining["Mother"]):
                        # Clue 12: Aniya is Alice's mother.
                        if (name == "Alice" and mother != "Aniya") or (name != "Alice" and mother == "Aniya"):
                            continue
                        # Clue 7: Janelle <-> carnations
                        if (flower == "carnations" and mother != "Janelle") or (mother == "Janelle" and flower != "carnations"):
                            continue

                        # Occupation choices
                        for occupation in list(remaining["Occupation"]):
                            # Clue 6: Teacher is in the first house.
                            if (i == 1 and occupation != "teacher") or (i != 1 and occupation == "teacher"):
                                continue
                            # Clue 11: Peter is a doctor.
                            if (name == "Peter" and occupation != "doctor") or (name != "Peter" and occupation == "doctor"):
                                continue
                            # Clue 4: daffodils to the right of engineer will be checked after assignment.

                            # Sports choices
                            for sport in list(remaining["FavoriteSport"]):
                                # Clue 1 + 2: Swimming <-> Roses <-> Eric
                                if (name == "Eric" and sport != "swimming") or (name != "Eric" and sport == "swimming"):
                                    continue
                                if (flower == "roses" and sport != "swimming") or (sport == "swimming" and flower != "roses"):
                                    continue
                                # Clue 5: Soccer <-> short
                                if (height == "short" and sport != "soccer") or (sport == "soccer" and height != "short"):
                                    continue
                                # Clue 8: Basketball <-> average
                                if (height == "average" and sport != "basketball") or (sport == "basketball" and height != "average"):
                                    continue

                                # Passed local constraints; propose candidate
                                cands.append((name, flower, height, mother, occupation, sport))
        return cands

    def backtrack(i):
        if i == 5:
            return True

        for cand in generate_candidates(i):
            add_assignment(i, cand)
            if check_partial_constraints():
                if backtrack(i + 1):
                    return True
            remove_assignment(i, cand)
        return False

    found = backtrack(1)
    if not found:
        raise RuntimeError("No solution found")

    # Build JSON output
    header = ["House", "Name", "Flower", "Height", "Mother", "Occupation", "FavoriteSport"]
    rows = []
    for h in range(1, 5):
        row = [
            str(h),
            solution[h-1]["Name"],
            solution[h-1]["Flower"],
            solution[h-1]["Height"],
            solution[h-1]["Mother"],
            solution[h-1]["Occupation"],
            solution[h-1]["FavoriteSport"],
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
